(function(){'use strict';
const C=FTCore,$=sel=>document.querySelector(sel),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let store;try{store=new C.Store(localStorage)}catch{store=new C.Store(null)}
let session=null,message='',errors=[],saveStatus=store.available?'Choose or start a session':'Storage unavailable — export progress before leaving',saveTimer=null,modalReturn=null,imported=null,printHTML='';
const money=x=>'$'+C.q(x).fixed(2),btn=(text,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`,math=v=>{const a=String(v).split('/');return a.length===2?`${a[0].startsWith('-')?'−':''}<span class="fraction"><span>${esc(a[0].replace(/^-/,'').replace(/−/g,''))}</span><span>${esc(a[1])}</span></span>`:esc(String(v).replace(/-/g,'−'))},snum=()=>session?C.stageNumber(session):0;
function save(){if(!session)return false;clearTimeout(saveTimer);try{store.save(session);saveStatus='Saved on this device · '+new Date().toLocaleTimeString();return true}catch(e){saveStatus=e.message==='CONFLICT'?'Newer work exists in another tab':e.message;if(e.message==='CONFLICT')conflict();return false}finally{const el=$('#save-status');if(el)el.textContent=saveStatus}}
function scheduleSave(){clearTimeout(saveTimer);saveStatus='Unsaved edits';const el=$('#save-status');if(el)el.textContent=saveStatus;saveTimer=setTimeout(save,500)}
function header(){return `<header><div><div class="brand">Food Truck</div><div class="credit">A WILLIAM MCADA PRODUCT</div></div><div class="toolbar"><span id="save-status" class="save-status" role="status">${esc(saveStatus)}</span>${session?btn('Save','save')+btn('Export progress','export'):''}${btn('Saved work','sessions')}${btn('Teacher','teacher')}</div></header>`}
function footer(){return `<footer><span>William McAda · Applied Math Projects</span><span>App ${C.VERSION} · Content ${C.CONTENT} · No accounts or tracking</span></footer>`}
function home(){return `<main id="main" class="shell" tabindex="-1"><div class="hero"><div><div class="eyebrow">Applied mathematics / project 02</div><h1>Good food.<br>A sound plan.</h1><p class="lead">One truck. Three hours. A business worth thinking through.</p><p>Scale a recipe, set your price, and discover what it takes to turn a busy festival into a profitable launch.</p><div class="stats"><div><strong>3 hours</strong><span>festival service</span></div><div><strong>2 plans</strong><span>one informed choice</span></div><div><strong>3 lessons</strong><span>about 45 minutes each</span></div></div><div class="actions">${btn('Start your food truck →','new','','primary')}${btn('Resume saved work','sessions')}</div></div><div class="visual">${FTArt.scene()}</div></div><div class="features"><div><h3>Make it yours</h3><p>Choose a menu identity and scale the ingredients for your stock.</p></div><div><h3>Follow the money</h3><p>Connect cost, revenue and profit through rules, tables and graphs.</p></div><div><h3>Learn from launch</h3><p>Account for every prepared meal. Compare a second plan and make your case.</p></div></div><p class="privacy">Use aliases instead of names. Work stays in this browser. Export progress before changing devices or clearing browser data. Classroom prices and demand forecasts are authored examples.</p></main>`}
function field(key){const d=C.definitions(session)[key],t=C.target(session,key),val=t.raw[key]||'',st=C.fieldState(session,key),error=errors.find(e=>e.key===key),readonly=!d.global&&session.plans[session.activePlan].frozen,attr=`id="f-${key}" data-field="${key}" ${readonly?'disabled':''}`;if(d.kind==='notRequired')return '';
let input;if(d.kind==='select'||d.kind==='choice')input=`<select ${attr}><option value="">Choose…</option>${d.options.map(([v,n])=>`<option value="${esc(v)}" ${val===v?'selected':''}>${esc(n)}</option>`).join('')}</select>`;else if(d.kind==='set')input=`<fieldset ${attr}><legend>${esc(d.label)}</legend><div class="checks">${d.options.map(([v,n])=>`<label><input type="checkbox" data-set="${key}" value="${v}" ${val.split(',').includes(v)?'checked':''} ${readonly?'disabled':''}>${esc(n)}</label>`).join('')}</div></fieldset>`;else if(d.kind==='text')input=`<textarea ${attr} maxlength="600">${esc(val)}</textarea>`;else input=`<input ${attr} value="${esc(val)}" maxlength="${d.kind==='numeric'?64:200}" inputmode="text" autocomplete="off" spellcheck="false" aria-describedby="hint-${key}" ${error?'aria-invalid="true"':''}>`;
return `<div class="field ${d.kind==='text'?'wide':''}">${d.kind!=='set'?`<label for="f-${key}">${esc(d.label)}${d.unit?' ('+esc(d.unit)+')':''}</label>`:''}${input}<small id="hint-${key}">${d.kind==='numeric'?'Calculator allowed · '+(d.unit==='%'?'round as labeled':'exact number or fraction'):d.kind==='expression'?'Enter a rule in x. Equivalent linear forms are accepted.':d.kind==='equation'?'Use =. Equivalent linear equalities are accepted.':d.kind==='text'?'Submitted for teacher review; grammar is not scored.':''}</small>${error?`<div class="feedback bad">${esc(error.message)}</div>`:['verified','overridden','needsRecheck'].includes(st)?`<div class="feedback ${st==='needsRecheck'?'bad':''}">${st==='verified'?'Checked':st==='overridden'?'Teacher bypass · provisional':'Needs recheck'}${t.evidence[key]?.carriedFrom?' · carried from Plan A':''}</div>`:''}</div>`}
function group(g,content=null){const ok=C.groupOK(session,g),a=session.plans[session.activePlan];return `<section class="group" id="group-${g}"><div class="group-head"><div><small>${g} · ${ok?'CURRENT':'YOUR WORK'}</small><h3>${C.labels[g]}</h3></div>${btn('?','help',`data-group="${g}" aria-label="Help: ${C.labels[g]}"`,'help')}</div>${content===null?`<div class="fields">${C.keys(session,g).map(field).join('')}</div>`:content}<div class="group-actions"><span class="muted">${ok?'Current checks recorded':g==='C09'?'Reasoning remains teacher-reviewed':'Check when you are ready.'}</span>${btn('Check '+g,'check',`data-group="${g}" ${a.frozen&&!['C09','C10'].includes(g)?'disabled':''}`,'primary')}</div></section>`}
function priceStock(kind){const a=session.plans[session.activePlan],frozen=a.frozen;return `<label>${kind==='p'?'Selling price (USD/portion)':'Prepared stock (portions)'}<select class="text" data-plan="${kind}" ${frozen?'disabled':''}>${(kind==='p'?[9,12,15]:[60,80,100,120]).map(n=>`<option value="${n}" ${a[kind]===n?'selected':''}>${kind==='p'?'$':''}${n}${kind==='q'?' · '+n/20+' batches':''}</option>`).join('')}</select></label>`}
const demandTable=()=>`<table><caption>Disclosed festival forecast</caption><thead><tr><th>Price per portion</th><th>Forecast demand</th></tr></thead><tbody>${Object.entries(C.demand).map(([p,d])=>`<tr><td>$${p}</td><td>${d} meals</td></tr>`).join('')}</tbody></table><p class="muted">Classroom assumptions—not predictions of a real market.</p>`;
function dataRecipe(){return `<table><caption>One classroom batch · 20 portions</caption><thead><tr><th>Item</th><th>Quantity</th><th>Price</th></tr></thead><tbody>${C.ingredients.map(([k,n,v,u,p])=>`<tr><td>${esc(n)}</td><td>${v} ${u}</td><td>${money(p)}/${u==='units'?'package':u}</td></tr>`).join('')}</tbody></table>`}
function graph(s,pid=s.activePlan,profit=false,teacher=false){const p=s.plans[pid],m=C.scenario(s,pid),ready=teacher||C.groupOK(s,'C06',pid),xs=Number(p.raw.xStep)||20,ys=profit?300:Number(p.raw.yStep)||200,xmin=0,xmax=120,ymin=profit?-600:0,ymax=profit?1200:1800,W=760,H=390,L=76,T=25,B=332,R=725,px=x=>L+(x-xmin)/(xmax-xmin)*(R-L),py=y=>B-(y-ymin)/(ymax-ymin)*(B-T);let body=`<rect width="760" height="390" fill="#fffef9"/>`;for(let x=0;x<=120;x+=xs)body+=`<path class="grid" d="M${px(x)} ${T}V${B}"/><text x="${px(x)}" y="${B+22}" text-anchor="middle">${x}</text>`;for(let y=ymin;y<=ymax;y+=ys)body+=`<path class="grid" d="M${L} ${py(y)}H${R}"/><text x="${L-10}" y="${py(y)+5}" text-anchor="end">${y}</text>`;body+=`<path class="axis" d="M${L} ${T}V${B}H${R}"/><text x="400" y="${H-10}" text-anchor="middle">Portions x · whole counts are feasible</text><text x="17" y="180" transform="rotate(-90 17 180)" text-anchor="middle">USD</text>`;if(profit){if(ready)body+=`<path d="M${px(0)} ${py(m.P(0).num())}L${px(120)} ${py(m.P(120).num())}" fill="none" stroke="#344e42" stroke-width="3"/><path d="M${L} ${py(0)}H${R}" stroke="#a54a38" stroke-dasharray="6 5"/><text x="650" y="50">Profit</text>`;}else{for(const kind of ['R','C']){const color=kind==='R'?'#aa3c2d':'#3c6b65';if(ready)body+=`<path d="M${px(0)} ${py(m[kind](0).num())}L${px(120)} ${py(m[kind](120).num())}" fill="none" stroke="${color}" stroke-width="3"/>`;for(const x of [0,60,100]){let xv,yv;try{xv=teacher?x:C.numeric(p.raw['point'+kind+x+'X']||'','portions').num();yv=teacher?m[kind](x).num():C.numeric(p.raw['point'+kind+x+'Y']||'','USD').num()}catch{continue}if(xv>=0&&xv<=120&&yv>=0&&yv<=1800)body+=`<circle cx="${px(xv)}" cy="${py(yv)}" r="5" fill="${color}"/>`;}body+=`<text x="${kind==='R'?480:600}" y="22" fill="${color}">${kind==='R'?'R revenue':'C expense'}</text>`;}if(ready)body+=`<circle cx="${px(m.crossing.num())}" cy="${py(m.R(m.crossing).num())}" r="8" fill="none" stroke="#b79532" stroke-width="3"/>`;}return `<svg class="graph" viewBox="0 0 ${W} ${H}" role="img" aria-label="${profit?'Signed profit graph':'Sold-all revenue and expense graph'}"><title>${profit?'Profit includes negative values':'Your table and ordered pairs have an equivalent data representation'}</title>${body}</svg>`}
function stageContent(){const s=session,n=snum(),a=s.plans[s.activePlan];
if(n===1)return `<p class="lead">Your pair has a trial stall at a community food festival. Plan one menu item for a three-hour service window.</p><div class="note"><strong>The sponsor's brief</strong><p>Earn at least $150 profit and leave no more than 10% of prepared stock unsold. A weaker plan is still worth analyzing.</p></div><div class="fields"><div class="field"><label for="team-alias">Team alias</label><input id="team-alias" data-meta="teamAlias" value="${esc(s.teamAlias)}" maxlength="64"></div><div class="field"><label for="truck-name">Truck name</label><input id="truck-name" data-meta="truckName" value="${esc(s.truckName)}" maxlength="64"></div><div class="field"><label for="planner">Who plans first?</label><select id="planner" data-meta="planner"><option value="A" ${s.planner==='A'?'selected':''}>Learner A — Planner</option><option value="B" ${s.planner==='B'?'selected':''}>Learner B — Planner</option></select></div></div><h2>Choose your menu identity</h2><div class="cards">${Object.entries(C.cuisines).map(([k,v])=>`<button class="card ${s.cuisineId===k?'selected':''}" data-action="cuisine" data-value="${k}" aria-pressed="${s.cuisineId===k}">${FTArt.menu(k)}<strong>${v}</strong></button>`).join('')}</div><p class="muted">All three fictional menu identities use the same classroom ingredient quantities and cost model. This is a mathematical plan, not a cooking recipe.</p><label class="checks"><input type="checkbox" data-meta="brief" ${s.brief?'checked':''}> We will consider both profit and unsold stock.</label><p>The Planner enters and explains. The Checker checks quantities, units and reasoning. Swap roles after lessons one and two.</p>`;
if(n===2)return `<p class="lead">Start with the prepared stock you intend to bring. You can confirm or revise it at Stock and service.</p><div class="plan-controls">${priceStock('q')}</div>${dataRecipe()}<div class="mini-art">${FTArt.concept('tray')}</div><div class="ratio" aria-label="Selected batch count">${Array.from({length:a.q/20},()=>'<span>20 portions</span>').join('')}</div>${group('C01')}`;
if(n===3)return `<p class="lead">Pay for every prepared meal—including its package. Keep those variable purchases separate from the fixed launch fees.</p>${dataRecipe()}<div class="note"><strong>Fixed once per launch</strong><p>Stall $200 · truck hire $150 · signs/setup $100</p></div>${group('C02',`<h4>One batch: line costs</h4><div class="fields">${C.ingredients.map(r=>field('base_'+r[0])).join('')}${field('baseTotal')}</div><hr class="section-rule"><h4>Your ${a.q} prepared portions</h4><div class="fields">${C.ingredients.map(r=>field('prepared_'+r[0])).join('')}${['preparedTotal','unitCost','fixedTotal'].map(field).join('')}</div><hr class="section-rule"><h4>Which costs vary with prepared stock?</h4><div class="fields">${[...C.ingredients.map(r=>'class_'+r[0]),'class_stall','class_hire','class_setup'].map(field).join('')}</div>`)}`;
if(n===4)return `<p class="lead">A price affects both contribution per sale and forecast demand. Read the whole table before choosing.</p>${demandTable()}<div class="plan-controls">${priceStock('p')}</div>${group('C03')}`;
if(n===5)return `<p class="lead">Build a theoretical sold-all model, then connect it to a table, a graph and the first profitable sale.</p><div class="notice"><strong>A different question from launch day</strong><p>Here x portions are prepared and all x are sold. The graph allows 0–120 whole portions. The real festival may sell fewer because of demand or service capacity.</p></div>${group('C04')}${group('C05')}${group('C06',`<h4>Revenue and expense table</h4><div class="fields">${[0,60,100].flatMap(x=>['R','C'].map(k=>field('table'+k+x))).join('')}</div><h4>Build the graph</h4><div class="fields">${['xAxis','yAxis','xStep','yStep'].map(field).join('')}</div><p class="muted">Enter each ordered pair independently. The verified lines appear after the graph check.</p><div class="fields">${[0,60,100].flatMap(x=>['R','C'].flatMap(k=>[field('point'+k+x+'X'),field('point'+k+x+'Y')])).join('')}</div><div style="margin-top:20px">${graph(s)}</div><div class="fields">${['crossX','crossY','lossAt30','lossMeaning'].map(field).join('')}</div>${C.groupOK(s,'C06')?'<h4>The same model as profit</h4>'+graph(s,s.activePlan,true):''}`)}`;
if(n===6)return `<p class="lead">How many meals can this truck actually sell? Preparation, demand and service are different limits.</p><div class="mini-art">${FTArt.concept('capacity')}</div><div class="note"><strong>Service notice</strong><p>32 meals per hour · 3 hours open</p><p>You can prepare food before opening. Preparing more than service capacity is allowed; selling more is not.</p></div><div class="plan-controls">${priceStock('q')}${priceStock('p')}</div>${demandTable()}${group('C07')}`;
if(n===7)return `<p class="lead">Launch follows the published forecast. There is no random sales roll.</p><div style="max-width:650px">${FTArt.scene(s.cuisineId)}</div><div class="note"><strong>${esc(s.truckName)} · Plan ${s.activePlan}</strong><p>${a.q} portions prepared · price ${money(a.p)} · ${C.valid(s,'sales')?esc(a.raw.sales)+' sales checked':'check predicted sales first'}</p></div>${group('C08')}`;
const A=C.scenario(s,'A'),B=s.plans.B?C.scenario(s,'B'):null;
return `<p class="lead">Keep the first launch. Explore a different price or stock quantity, then recommend either plan with evidence.</p>${!s.plans.A.frozen?'<div class="notice">Finish Plan A at Launch weekend before making the comparison.</div>':''}<div class="actions">${btn(s.plans.B?'Revise Plan B':'Create Plan B','createB','', 'primary')}${btn('View preserved Plan A','viewA')}${btn('Duplicate for a fresh comparison','freshCopy')}</div>${B?`<table><caption>Checked launch results</caption><thead><tr><th>Quantity</th><th>Plan A</th><th>Plan B</th></tr></thead><tbody>${[['Price',money(A.p),money(B.p)],['Prepared stock',A.q,B.q],['Sales',A.s,B.s],['Profit',money(A.profit),money(B.profit)],['Unsold portions',A.waste,B.waste],['Waste %',A.wastePercent.fixed(1)+'%',B.wastePercent.fixed(1)+'%']].map(([l,x,y],i)=>`<tr><th>${l}</th><td>${i<2||C.allPlanOK(s,'A')?x:'Needs checks'}</td><td>${i<2||C.allPlanOK(s,'B')?y:'Needs checks'}</td></tr>`).join('')}</tbody></table>${!C.different(s)?'<div class="notice">Plan B must change price or stock. Changing the cuisine does not change its mathematics.</div>':''}${group('C09')}${transferGroup()}${endingPanel()}`:'<p>Plan A is preserved when its launch checks are complete. Plan B begins with unchanged work carried forward; changed quantities require rechecking.</p>'}`;
}
function transferGroup(){return group('C10',`<p class="muted">Take turns. Each learner answers separately without the shared model on screen. Paper/oral submissions require a teacher record.</p><h4>Learner A</h4><p>Fixed fee $360; selling price $14; variable cost $5 per portion. Assume every prepared portion sells.</p><div class="fields">${['transferModeA','transferARule','transferACross','transferAFirst'].map(field).join('')}</div>${session.raw.transferModeA!=='digital'?`<p>Submission: ${C.transferSubmitted(session,'A')?'recorded · '+C.reviewStatus(session,'transferModeA'):'not recorded — ask the teacher'}</p>`:''}<hr class="section-rule"><h4>Learner B</h4><p>Prepare 70 portions at variable cost $4 each. Sell 56 at $10 each. Fixed fee is $200.</p><div class="fields">${['transferModeB','transferBRevenue','transferBExpense','transferBProfit','transferBWaste','transferBSell','transferBBasis'].map(field).join('')}</div>${session.raw.transferModeB!=='digital'?`<p>Submission: ${C.transferSubmitted(session,'B')?'recorded · '+C.reviewStatus(session,'transferModeB'):'not recorded — ask the teacher'}</p>`:''}`)}
function endingPanel(){const o=C.outcome(session),p=session.raw.chosenPlan||'B',m=C.scenario(session,session.plans[p]?p:'A');return `<section class="group"><div class="eyebrow">Your business decision</div><h2>${o.title}</h2>${FTArt.scene(session.cuisineId,o.code)}${!['draft','provisional'].includes(o.code)?`<p>Plan ${p} prepares ${m.q} portions at ${money(m.p)}. It serves ${m.s} customers, earns ${money(m.profit)} profit and leaves ${m.waste} portions unsold (${m.wastePercent.fixed(1)}%).</p><p>Sales limited by: ${m.limits.join(' and ')}.</p>`:'<p>Finish missing or stale evidence. Teacher bypass remains visible and provisional.</p>'}<p class="muted">Reasoning review: ${C.reviewStatus(session,'reason')}. First and final responses, assistance and imported history remain distinct.</p><div class="actions">${btn('Preview / print report','report')}${btn('Print menu / truck card','menu')}${btn('Export progress','export')}</div></section>`}
function sidebar(){const s=session,a=s.plans[s.activePlan];return `<aside class="sidebar" aria-label="Current truck plan">${FTArt.menu(s.cuisineId)}<div class="eyebrow">${esc(s.truckName||'Your food truck')}</div><h3>Plan ${s.activePlan}</h3><dl><dt>Menu identity</dt><dd>${C.cuisines[s.cuisineId]}</dd><dt>Prepared portions</dt><dd>${a.q}</dd><dt>Price per portion</dt><dd>${money(a.p)}</dd><dt>Planner / Checker</dt><dd>${s.planner} / ${s.planner==='A'?'B':'A'}</dd></dl><p class="muted">Classroom costing model. Actual quantities are revealed after their checks.</p>${btn('Glossary','glossary')}${a.frozen?'<p class="pill">Plan A preserved</p>':''}</aside>`}
function render(focus=false){$('#app').innerHTML=header()+(session?`<div class="shell"><nav class="stages" aria-label="Journey stages">${C.stages.map((name,i)=>btn(`<b>${String(i+1).padStart(2,'0')}</b>${name}`,'stage',`data-stage="${i+1}" ${snum()===i+1?'aria-current="step"':''}`,snum()===i+1?'active':'')).join('')}</nav>${message?`<div class="banner" role="status">${esc(message)}</div>`:''}${!store.available?'<div class="notice">Device storage is unavailable. Keep this page open and export progress frequently.</div>':''}<div class="workspace"><main id="main" tabindex="-1"><div class="eyebrow">Stage ${snum()} of 8 · ${esc(session.teamAlias||'Your team')} · Plan ${session.activePlan}</div><h1>${C.stages[snum()-1]}</h1>${errors.length?`<div class="error-summary" id="errors" role="alert" tabindex="-1"><strong>Check these fields</strong>${errors.map(e=>`<div>${btn(esc(e.message),'focus',`data-key="${esc(e.key)}"`)}</div>`).join('')}</div>`:''}${stageContent()}<div class="actions">${snum()>1?btn('← Back','back'):''}${snum()<8?btn('Check & continue →','next','','primary'):btn('Check final submission','finish','','primary')}${btn('Preview / print report','report')}</div></main>${sidebar()}</div></div>`:home())+footer();if(focus)($('#errors')||$('#main'))?.focus()}
function dialog(title,body){modalReturn=document.activeElement;$('#modal-host').innerHTML=`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="dialog-head"><h2 id="modal-title">${esc(title)}</h2>${btn('Close','close','aria-label="Close dialog"')}</div><div id="dialog-error" role="alert"></div>${body}</section></div>`;$('.dialog button')?.focus()}
function close(){const el=modalReturn;$('#modal-host').innerHTML='';if(el?.isConnected)el.focus()}
function download(obj,name){const text=JSON.stringify(obj,null,2);if(new TextEncoder().encode(text).length>5*1024*1024)throw Error('Export exceeds 5 MiB. Keep the page open and contact the teacher.');const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportSession(){if(!session)throw Error('Start or resume a session.');save();download(session,'FoodTruck-'+session.sessionId+'.json');message='Progress download requested. Check that the file was saved before leaving.'}
function savedWork(){const rows=store.list();dialog('Saved work',`<p>Each session contains both plans, answers, attempts, reviews and report state. Downloaded backups are separate.</p><div class="actions">${btn('New session','new')}${btn('Import progress','import')}${btn('Export selected backup','backup')}</div><p class="muted">Select up to 25 sessions per backup. Export multiple batches for larger collections.</p>${rows.length?rows.map(row=>`<div class="row"><label class="checks"><input type="checkbox" data-backup="${esc(row.id)}" ${rows.length<=25&&!row.error?'checked':''} ${row.error?'disabled':''}>${row.error?'Unreadable saved session':esc(row.session.teamAlias||'Unnamed pair')}</label><p class="muted">${row.error?esc(row.error):`Stage ${C.stageNumber(row.session)} · ${esc(row.session.truckName)} · ${esc(row.session.updatedAt)}`}</p><div class="actions">${!row.error?btn('Resume','resume',`data-id="${esc(row.id)}"`)+btn('Duplicate','duplicate',`data-id="${esc(row.id)}"`):''}${btn('Delete','delete',`data-id="${esc(row.id)}"`,'danger')}</div></div>`).join(''):'<p>No saved Food Truck sessions on this device.</p>'}<div class="actions">${btn('Clear all Food Truck sessions','clearAll','','danger')}</div>`)}
function confirmDelete(ids){const entries=store.list().filter(r=>ids.includes(r.id));dialog('Delete saved work?',`<p>Delete <strong>${ids.length} Food Truck session(s)</strong>, including both plans, attempts and reviews?</p><p>${entries.map(r=>esc(r.session?.teamAlias||r.id)).join(', ')}</p><p>Local deletion cannot be undone without an exported backup. Downloaded files, Road Trip and fixed classroom content are not removed.</p><div class="actions">${btn('Cancel','sessions')}${btn('Export backup before deletion','deleteBackup')}${btn('Confirm deletion','confirmDelete','','danger')}</div>`);$('#modal-host').dataset.deleteIds=JSON.stringify(ids)}
function backupRows(ids){const rows=ids.map(id=>store.read(id));if(rows.some(x=>!x))throw Error('A selected record cannot be read.');download(C.bundle(rows),'FoodTruck-backup-'+Date.now()+'.json')}
function teacher(){dialog('Teacher workspace',`<p>Local classroom controls. Answers are not securely hidden; records are not tamper-proof. Use aliases.</p><div class="actions">${btn('Teacher reference','teacherPrint')}${btn('Individual transfer slips','slips')}${btn('Run diagnostics','diagnostics')}${btn('Export diagnostics','diagnosticExport')}</div>${session?`<hr class="section-rule"><h3>Review or record a submission</h3><div class="review-form"><label>Reviewer alias<input class="text" id="reviewer" maxlength="64"></label><label>Review target<select class="text" id="review-key"><option value="reason">Recommendation reasoning / oral response</option><option value="transferModeA">Learner A paper/oral submission</option><option value="transferModeB">Learner B paper/oral submission</option></select></label><label>Review status<select class="text" id="review-status"><option value="pending">Submitted — pending review</option><option value="verified">Reviewed</option><option value="revise">Revise</option></select></label><label>Observation / response note<textarea class="text" id="review-note" maxlength="400"></textarea></label>${btn('Record review / submission','review','','primary')}</div><h3>Bypass a faulty or inaccessible checkpoint</h3><p class="muted">Active Plan ${session.activePlan}. Bypassed evidence remains provisional.</p><label>Checkpoint<select class="text" id="bypass-group">${Object.entries(C.labels).map(([g,n])=>`<option value="${g}">${g} ${n}</option>`).join('')}</select></label><label>Reason<textarea class="text" id="bypass-reason" maxlength="400"></textarea></label>${btn('Record teacher bypass','bypass')}`:''}`)}
function value(s,key,pid){const d=C.definitions(s,pid)[key],t=C.target(s,key,pid),st=C.fieldState(s,key,pid),raw=t.raw[key]||'—';return `${math(raw)} <small>(${st==='verified'?'checked':st==='overridden'?'bypassed':st==='notRequired'?'paper/oral':st==='needsRecheck'?'needs recheck':'not checked'})</small>`}
function paperHead(page,title){return `<div class="paper-head">A WILLIAM MCADA PRODUCT · Food Truck · ${esc(session?.teamAlias||'Teacher reference')} · ${new Date().toISOString().slice(0,10)} · App ${C.VERSION} / Content ${C.CONTENT} · ${title} page ${page}</div>`}
function studentReport(){const s=session,pid=s.plans[s.raw.chosenPlan]?s.raw.chosenPlan:s.activePlan,a=s.plans[pid],o=C.outcome(s),v=k=>value(s,k,pid),m=C.scenario(s,pid);const pages=[];
pages.push(`<div class="paper">${paperHead(1,'Business report')}<div class="menu-art">${FTArt.menu(s.cuisineId)}</div><div class="eyebrow">${o.title}${s.imported?' · Imported evidence':''}</div><h2>${esc(s.truckName||'Our food truck')}</h2><p>Recommended/displayed Plan ${pid} · ${C.cuisines[s.cuisineId]} · ${money(a.p)} per portion · ${a.q} prepared</p><p>Planner ${s.planner}; Checker ${s.planner==='A'?'B':'A'}. Three-hour festival. Sponsor targets: profit ≥$150 and waste ≤10%. Classroom costing model.</p><h3>Recipe and purchasing ledger</h3><p>Batch factor: ${v('factor')}. One batch makes 20 portions.</p><table><thead><tr><th>Ingredient</th><th>Prepared quantity</th><th>Unit price</th><th>Base line cost</th><th>Prepared cost</th></tr></thead><tbody>${C.ingredients.map(([k,n,q,u,p])=>`<tr><td>${n}</td><td>${v('qty_'+k)} ${u}</td><td>${money(p)}/${u}</td><td>${v('base_'+k)}</td><td>${v('prepared_'+k)}</td></tr>`).join('')}</tbody></table><p>Batch variable total: ${v('baseTotal')} USD. Prepared variable total: ${v('preparedTotal')} USD.</p><p>Unit cost: ${v('unitCost')} USD/portion. Fixed launch expense: ${v('fixedTotal')} USD.</p><p>Fixed fees: stall200 + hire150 + setup100 USD. Packaging is included for every prepared portion.</p><h3>Price and contribution</h3><p>Contribution: ${v('contribution')} USD/portion. Markup: ${v('markup')}%.</p><p>Markup denominator: ${esc(a.raw.markupBase||'—')}. Contribution interpretation: ${esc(a.raw.contributionMeaning||'—')}.</p><h3>Cost classification</h3><p>${[...C.ingredients.map(r=>[r[0],r[1]]),['stall','Stall'],['hire','Hire'],['setup','Setup']].map(([k,n])=>`${n}: ${esc(a.raw['class_'+k]||'—')}`).join(' · ')}</p><p>This draft/report records submitted work; unchecked values are not certified.</p></div>`);
pages.push(`<div class="paper">${paperHead(2,'Business report')}<h2>Show how the numbers work</h2><p>Sold-all assumption: x portions prepared and all x sold. Whole counts 0–120. Actual festival sales may be lower.</p><p class="formula">R(x) = ${v('revenueRule')} · C(x) = ${v('expenseRule')}</p><p class="formula">P(x) = ${v('profitRule')}</p><p>Profit coefficient: ${v('profitSlope')} USD/portion; constant: ${v('profitConstant')} USD.</p><table><thead><tr><th>Portions</th><th>Revenue</th><th>Expense</th><th>R point entered</th><th>C point entered</th></tr></thead><tbody>${[0,60,100].map(x=>`<tr><td>${x}</td><td>${v('tableR'+x)}</td><td>${v('tableC'+x)}</td><td>(${esc(a.raw['pointR'+x+'X']||'—')}, ${esc(a.raw['pointR'+x+'Y']||'—')})</td><td>(${esc(a.raw['pointC'+x+'X']||'—')}, ${esc(a.raw['pointC'+x+'Y']||'—')})</td></tr>`).join('')}</tbody></table>${graph(s,pid)}<p>Crossing (${v('crossX')}, ${v('crossY')}); profit at30: ${v('lossAt30')} USD. ${C.groupOK(s,'C06',pid)?'Verified lines shown.':'Only entered points shown; plotting checks pending.'}</p><p>Equality: ${v('breakEquation')}. Exact crossing: ${v('crossing')}.</p><p>First whole non-loss: ${v('firstNonLoss')}; first positive profit: ${v('firstProfit')}. Before: ${v('profitBefore')} USD; at: ${v('profitAt')} USD.</p></div>`);
pages.push(`<div class="paper">${paperHead(3,'Business report')}<h2>A launch. A revision. A decision.</h2><table><thead><tr><th>Quantity</th><th>Plan A</th><th>Plan B</th></tr></thead><tbody>${[['Price','p'],['Prepared stock','q']].map(([l,k])=>`<tr><td>${l}</td><td>${s.plans.A[k]}</td><td>${s.plans.B?.[k]??'Not created'}</td></tr>`).join('')}${[['Capacity','capacity'],['Demand','forecastDemand'],['Sales','sales'],['Revenue USD','actualRevenue'],['Expense USD','actualExpense'],['Profit USD','actualProfit'],['Unsold portions','waste'],['Waste %','wastePercent'],['Sell-through %','sellThrough'],['P(s) overstatement USD','overstatement']].map(([l,k])=>`<tr><td>${l}</td><td>${value(s,k,'A')}</td><td>${s.plans.B?value(s,k,'B'):'—'}</td></tr>`).join('')}</tbody></table><p>Limits A: ${esc(s.plans.A.raw.limits||'—')}; B: ${esc(s.plans.B?.raw.limits||'—')}. Expense uses all prepared portions.</p><p>Profit B−A: ${v('deltaProfit')}; waste B−A: ${v('deltaWaste')}.</p><h3>Recommendation: Plan ${esc(s.raw.chosenPlan||'—')}</h3><p>${esc(s.raw.evidenceMetric||'—')}: ${v('evidenceValue')}</p><p style="overflow-wrap:anywhere">${esc(s.raw.reason||'No recommendation submitted.')}</p><p>Reasoning review: ${C.reviewStatus(s,'reason')}. ${o.title}. ${!['draft','provisional'].includes(o.code)?`Profit ${money(m.profit)}; ${m.waste} portions unsold; sales limited by ${m.limits.join(' and ')}.`:'Complete current checks or review active bypasses.'}</p></div>`);
pages.push(`<div class="paper">${paperHead(4,'Business report')}<h2>Individual work and learning evidence</h2><h3>Learner A</h3><p>Fee360, price14, variable5. Mode: ${esc(s.raw.transferModeA)}. P(x): ${v('transferARule')}; break-even: ${v('transferACross')}; first positive profit: ${v('transferAFirst')}.</p><p>Submission: ${C.transferSubmitted(s,'A')?'digital/recorded':'not recorded'} · review ${C.reviewStatus(s,'transferModeA')}.</p><h3>Learner B</h3><p>Prepare70, sell56, price10, variable4, fee200. Mode: ${esc(s.raw.transferModeB)}. Revenue: ${v('transferBRevenue')}; expense: ${v('transferBExpense')}; profit: ${v('transferBProfit')}; waste: ${v('transferBWaste')}; sell-through: ${v('transferBSell')}%.</p><p>Submission: ${C.transferSubmitted(s,'B')?'digital/recorded':'not recorded'} · review ${C.reviewStatus(s,'transferModeB')}.</p><h3>First attempts and final evidence</h3><table class="evidence-table"><thead><tr><th>Checkpoint</th><th>First checked fields correct</th><th>Final current</th><th>Attempts / help</th></tr></thead><tbody>${Object.entries(C.labels).map(([g,n])=>{const list=s.attempts.filter(a=>a.checkpoint===g),first=new Map();for(const a of list){const key=a.plan+':'+a.key+':'+a.fingerprint;if(!first.has(key))first.set(key,a)}return `<tr><td>${g} ${n}</td><td>${[...first.values()].filter(a=>a.passed).length}/${first.size} field/context first checks</td><td>${C.groupOK(s,g,pid)?'current':'needs checks'}</td><td>${list.length} / ${s.support.filter(x=>x.group===g).length}</td></tr>`}).join('')}</tbody></table><p>Counts describe field submissions, not a mastery score. Plan B may carry unchanged evidence from A. The JSON export preserves raw first/final answers, timestamps, contexts, revisions and reviews.</p><p>${s.teacherOverrides.length} historical bypass records. Imported history: ${s.imported?'yes':'no'}. Separate learner work requires teacher observation; this browser does not certify independence.</p><p>First complete analyzed submission: ${esc(s.completedAt||'not yet complete')}.</p></div>`);return pages.join('')}
function teacherReport(){const rows=[];for(const p of [9,12,15])for(const q of [60,80,100,120]){const m=C.model(p,q);rows.push(`<tr><td>${p}</td><td>${q}</td><td>${m.s}</td><td>${m.revenue.fixed(2)}</td><td>${m.expense.fixed(2)}</td><td>${m.profit.fixed(2)}</td><td>${m.waste} / ${m.wastePercent.fixed(1)}%</td><td>${C.business(m).title}</td></tr>`)}return `<div class="paper">${paperHead(1,'Teacher reference')}<h2>Food Truck · answer reference</h2><p>Classroom constants: batch20; ingredient line costs10,18,40,10,12 → batch90 → variable4.50. Fixed450. Service32×3=96.</p><p>At q100: quantities10kg,15kg,10kg,2.5L,100 packages; prepared lines50,90,200,50,60; variable total450.</p><table><thead><tr><th>p</th><th>Contribution</th><th>Markup</th><th>Crossing</th><th>First non-loss / profit</th></tr></thead><tbody>${[9,12,15].map(p=>{const m=C.model(p);return `<tr><td>${p}</td><td>${m.c.fixed(2)}</td><td>${m.markup.fixed(1)}%</td><td>${math(m.crossing.str())}</td><td>${m.firstNonLoss} / ${m.firstProfit}</td></tr>`}).join('')}</tbody></table><p>R=px; C=450+4.5x; P=(p−4.5)x−450. Accept equivalent forms, e.g.12x−(450+4.5x). A right value at one x is insufficient. Markup divides by cost, not selling price.</p><table><thead><tr><th>p</th><th>q</th><th>s</th><th>Revenue</th><th>Expense</th><th>Profit</th><th>Waste</th><th>Business outcome</th></tr></thead><tbody>${rows.join('')}</tbody></table><p>Outcomes assume complete current evidence with no bypass. $9 break-even100 cannot be reached with service capacity96; correct losses must not be rejected.</p></div><div class="paper">${paperHead(2,'Teacher reference')}<h2>Representations, revision and review</h2><p>At p12, R(0,60,100)=0,720,1200; C=450,720,900; crossing(60,720). At p15 crossing(${math('300/7')},${math('4500/7')}). Exact fraction required.</p><p>Launch s=min(q,D,96); expense450+4.5q. At p12,q100:90 sold, revenue1080, expense900, profit180, waste10, sell-through90%. P(90)=225 overstates by45.</p><p>A=(12,100),B=(12,80): profit change−30, waste change−10. B=(15,60): profit change0, waste change−10. Either recommendation may be defensible.</p><h3>Individual transfer</h3><p>A: P(x)=9x−360; equality40; first positive41. B: revenue560, expense480, profit80, waste14, sell-through80%, prepared stock basis.</p><h3>Accepted forms</h3><p>4.5=4.50=9/2. Linear expanded/factored equivalents pass. $150 or150 USD in a total-money field; USD/portion is not a total. Counts require exact integer values; percentages rounded half-up to the stated0.1%.</p><h3>Misconceptions to inspect</h3><p>Revenue is not profit. Fixed fees are paid once. Unsold prepared food still costs money. Break-even is not always the first profitable sale. Demand is not capacity. Check all tied limits.</p><h3>Teacher review</h3><p>Record reasoning or oral/paper transfer with an alias and observation. Structural submission does not grade prose. Teacher bypass remains provisional. First attempts, assistance, carried-forward and imported evidence do not establish independent mastery.</p><h3>Classroom operation</h3><p>Pairs swap roles after lessons1/2 and export progress. Test the actual iPad, school network and printer. Print A4/Letter portrait100%, browser headers/footers off. Keep student reports, answer reference and transfer slips separate.</p></div>`}
function slips(){return ['A','B'].map((a,i)=>`<div class="paper">${paperHead(i+1,'Individual transfer')}<h2>Learner ${a} · individual work</h2><p>Alias: _______________________ Date: _______________________</p>${a==='A'?'<p>Fixed fee $360. Price $14 per portion. Variable cost $5 per portion. Assume all prepared portions sell.</p><h3>Write the profit rule.</h3><p>P(x) = __________________________________________</p><h3>Find break-even.</h3><p>________________________________________________</p><h3>Find the first whole count with positive profit.</h3><p>________________________________________________</p>':'<p>Prepare 70 portions at variable cost $4 each. Sell 56 at $10 each. Fixed fee $200.</p>'+['Revenue','Expense','Profit','Unsold portions','Sell-through percent','Does variable expense use prepared or sold portions?'].map(x=>`<h3>${x}</h3><p>________________________________________________</p>`).join('')}<p>Show your work separately. Teacher review: ______________________</p></div>`).join('')}
function menuReport(){const s=session,p=s.plans[s.raw.chosenPlan]?s.raw.chosenPlan:s.activePlan,a=s.plans[p];return `<div class="paper">${paperHead(1,'Menu / truck display card')}<div class="eyebrow">Our festival concept · Plan ${p}</div><h1>${esc(s.truckName||'Food Truck')}</h1><div class="scene">${FTArt.scene(s.cuisineId,C.outcome(s).code)}</div><h2>${C.cuisines[s.cuisineId]} · ${money(a.p)}</h2><p>Three-hour festival · ${a.q} portions planned · ${esc(s.teamAlias)}</p><p>${C.outcome(s).title}. Fictional classroom menu and pricing; not a real food service offer.</p><p>A WILLIAM MCADA PRODUCT · William McAda</p></div>`}
function preview(kind){if(['student','menu'].includes(kind)&&!session)throw Error('Start or resume a session first.');printHTML=kind==='teacher'?teacherReport():kind==='slips'?slips():kind==='menu'?menuReport():studentReport();$('#print-root').innerHTML=printHTML;dialog('Print preview',`<p>Use A4 or Letter, portrait, 100% scale. Disable browser headers/footers. ${kind==='student'?'Four student pages.':kind==='teacher'?'Two teacher reference pages.':kind==='slips'?'Two separate learner slips; no answers.':'One menu/display page.'}</p><div class="actions">${btn('Print / save PDF','print','','primary')}${btn('Close preview','close')}</div><div class="report-preview">${printHTML}</div>`)}
function prereqs(g){const order=['C01','C02','C03','C04','C05','C06','C07','C08'];if(g==='C09')return C.different(session)&&C.allPlanOK(session,'A')&&C.allPlanOK(session,'B')?[]:['Check both distinct plans first.'];if(g==='C10')return C.groupOK(session,'C09')?[]:['Submit the comparison first.'];return order.slice(0,order.indexOf(g)).filter(x=>!C.groupOK(session,x)).map(x=>'Finish '+x+' '+C.labels[x]+' first.');}
function checkGroup(g){const missing=prereqs(g);if(missing.length){errors=missing.map(message=>({key:'group-'+g,message}));return false;}errors=C.check(session,g);save();return !errors.length}
function next(){const n=snum();errors=[];if(n===1){for(const [k,label]of [['teamAlias','team alias'],['truckName','truck name']])if(!session[k].trim())errors.push({key:k,message:'Enter a '+label+'.'});if(!session.brief)errors.push({key:'brief',message:'Confirm both sponsor targets.'});}else{const missing=C.missing(session,n);if(missing.length)errors=missing.map(g=>({key:'group-'+g,message:'Recheck '+g+' '+C.labels[g]+' before continuing.'}));else for(const g of C.stageGroups(n)){if(!checkGroup(g))break;}}
if(errors.length){render(true);return;}if(n===7&&session.activePlan==='A')C.freeze(session);if(n===3||n===5){message='Lesson '+(n===3?'1':'2')+' complete. Export progress and swap Planner/Checker roles.';session.planner=session.planner==='A'?'B':'A';}else message='';session.currentStage='FT-S'+String(Math.min(n+1,8)).padStart(2,'0');session.maxStage=Math.max(session.maxStage,n+1);save();render(true)}
function conflict(){dialog('Newer saved work found',`<p>Another tab saved a newer revision. Keep your current edits as a separate copy, or reload the stored session.</p><div class="actions">${btn('Reload stored session','conflictReload')}${btn('Save as copy','conflictCopy','','primary')}${btn('Export current edits','export')}</div>`)}
function focusField(key){const ids={teamAlias:'team-alias',truckName:'truck-name',brief:'main'};const el=document.getElementById('f-'+key)||document.getElementById(key)||document.getElementById(ids[key]||'main');el?.scrollIntoView({block:'center'});el?.focus()}
$('#app').addEventListener('input',e=>{const el=e.target;try{if(el.dataset.field){C.setRaw(session,el.dataset.field,el.value);scheduleSave();}else if(el.dataset.meta&&el.tagName!=='SELECT'&&el.type!=='checkbox'){session[el.dataset.meta]=el.value;scheduleSave();}}catch(err){message=err.message;render();}});
$('#app').addEventListener('change',e=>{const el=e.target;try{if(el.dataset.plan){C.changePlan(session,el.dataset.plan,el.value);message='Plan '+session.activePlan+' updated. Only affected answers need rechecking; earlier responses are retained.';errors=[];save();render();}else if(el.dataset.set){const name=el.dataset.set,values=[...document.querySelectorAll(`input[data-set="${name}"]:checked`)].map(x=>x.value);C.setRaw(session,name,values.join(','));scheduleSave();}else if(el.dataset.field){C.setRaw(session,el.dataset.field,el.value);save();if(['transferModeA','transferModeB','chosenPlan','evidenceMetric','xStep','yStep'].includes(el.dataset.field))render();}else if(el.dataset.meta){session[el.dataset.meta]=el.type==='checkbox'?el.checked:el.value;save();}}catch(err){message=err.message;render();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{
if(action==='close'){close();return;}
if(action==='new'){clearTimeout(saveTimer);session=C.newSession();message='';errors=[];close();save();render(true);return;}
if(action==='save'){save();return;}
if(action==='sessions'){savedWork();return;}
if(action==='export'){exportSession();if(!$('.dialog'))render();return;}
if(action==='resume'){clearTimeout(saveTimer);session=store.read(b.dataset.id);if(!session)throw Error('This session no longer exists.');errors=[];message='Saved work resumed.';saveStatus='Loaded saved work';close();render(true);return;}
if(action==='duplicate'||action==='freshCopy'){const source=action==='duplicate'?store.read(b.dataset.id):session;session=C.duplicate(source,action==='freshCopy');message='Separate copy created. The original session remains.';errors=[];save();close();render(true);return;}
if(action==='backup'){const ids=[...document.querySelectorAll('[data-backup]:checked')].map(x=>x.dataset.backup);backupRows(ids);$('#dialog-error').textContent='Backup download requested. Check the file before deleting any work.';return;}
if(action==='delete'){confirmDelete([b.dataset.id]);return;}
if(action==='clearAll'){const ids=store.ids();if(!ids.length)throw Error('There are no stored Food Truck sessions to clear.');confirmDelete(ids);return;}
if(action==='deleteBackup'){backupRows(JSON.parse($('#modal-host').dataset.deleteIds));$('#dialog-error').textContent='Backup download requested. Confirm that it exists before choosing deletion.';return;}
if(action==='confirmDelete'){const ids=JSON.parse($('#modal-host').dataset.deleteIds);clearTimeout(saveTimer);try{store.remove(ids);}finally{if(session&&ids.includes(session.sessionId)&&!store.ids().includes(session.sessionId))session=null;}saveStatus='Saved-work list updated';render();savedWork();return;}
if(action==='import'){$('#import-file').click();return;}
if(action==='importCopies'||action==='importReplace'){if(!imported)throw Error('Choose a progress file first.');const rows=imported.map(x=>C.clone(x));for(const r of rows){if(action==='importCopies'){r.duplicateOf=r.sessionId;r.sessionId=C.id();r.localRevision=0;r.teamAlias=(r.teamAlias+' — copy').slice(0,64);}else{const existing=store.read(r.sessionId);r.localRevision=(existing?.localRevision||0)+1;}r.imported=true;}store.saveMany(rows);session=rows[0];imported=null;message='Imported '+rows.length+' session(s). History is labeled imported; current mathematics was revalidated.';errors=[];close();render(true);return;}
if(action==='confirmReplace'){dialog('Replace matching sessions?',`<p>Replace matching Food Truck identities from these validated sessions: ${imported.map(s=>esc(s.teamAlias)).join(', ')}. Original local records will be overwritten; recovery requires a backup.</p><div class="actions">${btn('Cancel','sessions')}${btn('Export matching originals','replaceBackup')}${btn('Confirm replacement','importReplace','','danger')}</div>`);return;}
if(action==='replaceBackup'){backupRows(imported.map(s=>s.sessionId).filter(id=>store.ids().includes(id)));$('#dialog-error').textContent='Originals download requested. Confirm the backup was saved.';return;}
if(action==='teacher'){teacher();return;}
if(action==='diagnostics'){const r=C.diagnostics();dialog('Local diagnostic',`<p>Pure mathematics checks only; no student work is changed.</p>${r.map(x=>`<p>${x.passed?'Passed':'Failed'} · ${x.name}</p>`).join('')}`);return;}
if(action==='diagnosticExport'){download({project:'food-truck',appVersion:C.VERSION,contentVersion:C.CONTENT,checks:C.diagnostics(),stage:session?.currentStage||null,status:session?C.outcome(session).code:null},'FoodTruck-diagnostic.json');return;}
if(action==='teacherPrint'){preview('teacher');return;}
if(action==='slips'){preview('slips');return;}
if(action==='review'){C.review(session,$('#review-key').value,$('#reviewer').value,$('#review-note').value,$('#review-status').value);save();close();render();message='Review recorded.';return;}
if(action==='bypass'){C.bypass(session,$('#bypass-group').value,$('#reviewer').value,$('#bypass-reason').value);save();close();message='Teacher bypass recorded. Required completion remains provisional.';render();return;}
if(action==='conflictReload'){clearTimeout(saveTimer);session=store.read(session.sessionId);close();errors=[];message='Loaded the newer saved revision.';render();return;}
if(action==='conflictCopy'){session=C.duplicate(session);save();close();message='Current edits saved as a separate copy.';render();return;}
if(action==='help'){const g=b.dataset.group;if(session.support.length>=10000)throw Error('Support history is full. Export this session.');session.support.push({group:g,plan:session.activePlan,at:C.now()});save();const h=C.help[g];dialog('Help: '+h[0],['Meaning and format','What to do','Different-number example'].map((t,i)=>`<h3>${t}</h3><p>${h[i+1]}</p>`).join(''));return;}
if(action==='glossary'){dialog('Business glossary',`<div class="cards">${FTArt.concept('ingredients')}${FTArt.concept('sauce')}${FTArt.concept('packaging')}</div><dl>${Object.entries({Batch:'One complete recipe quantity.',Portion:'One meal offered for sale.','Fixed cost':'Expense paid once for the launch.','Variable cost':'Expense for each prepared portion.',Revenue:'Money from sales.',Contribution:'Price minus variable cost per portion.',Markup:'Increase above cost, as a percent of cost.',Profit:'Revenue minus all expenses.','Break-even':'Revenue equals expense; profit is zero.',Demand:'Forecast number of customers wanting a meal.',Capacity:'Maximum meals served during the opening window.',Waste:'Prepared portions left unsold.','Sell-through':'Sold portions as a percent of prepared stock.'}).map(([k,v])=>`<dt><strong>${k}</strong></dt><dd>${v}</dd>`).join('')}</dl>`);return;}
if(action==='report'){preview('student');return;}
if(action==='menu'){preview('menu');return;}
if(action==='print'){$('#print-root').innerHTML=printHTML;window.print();return;}
if(action==='focus'){focusField(b.dataset.key);return;}
if(action==='cuisine'){session.cuisineId=b.dataset.value;save();render();return;}
if(action==='next'){next();return;}
if(action==='back'){session.currentStage='FT-S'+String(Math.max(1,snum()-1)).padStart(2,'0');errors=[];message='';save();render(true);return;}
if(action==='stage'){const n=Number(b.dataset.stage);if(n>session.maxStage){message='Complete the preceding stage to open '+C.stages[n-1]+'.';render();return;}session.currentStage='FT-S'+String(n).padStart(2,'0');errors=[];message='';save();render(true);return;}
if(action==='check'){checkGroup(b.dataset.group);render(true);return;}
if(action==='createB'){C.createB(session);errors=[];message='Plan B starts as a copy. Change its price or stock, then recheck affected work.';save();render(true);return;}
if(action==='viewA'){session.activePlan='A';session.currentStage='FT-S07';errors=[];message='Plan A is preserved. Its inputs cannot be changed; create or revise Plan B.';save();render(true);return;}
if(action==='finish'){errors=[];if(!C.allPlanOK(session,'A')||!C.allPlanOK(session,'B')||!C.different(session)){message='Complete two distinct checked plans before the final submission.';render(true);return;}for(const g of ['C09','C10'])if(!checkGroup(g))break;for(const who of ['A','B'])if(!C.transferSubmitted(session,who))errors.push({key:'transferMode'+who,message:'Ask the teacher to record learner '+who+' paper/oral submission.'});const o=C.outcome(session);if(!['draft'].includes(o.code)&&!session.completedAt)session.completedAt=C.now();message=errors.length?'Complete the remaining fields.':o.title+'. Review status stays visible.';save();render(true);return;}
}catch(err){if($('.dialog'))$('#dialog-error').textContent=err.message;else{message=err.message;render();}}});
$('#import-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Import files must be at most 5 MiB.');imported=C.parseImport(await file.text());dialog('Review import',`<p>${imported.length} session(s) validated. Existing work has not changed.</p>${imported.map(s=>`<div class="row"><strong>${esc(s.teamAlias)}</strong><p>Stage ${C.stageNumber(s)} · App ${esc(s.appVersion)} · ${store.ids().includes(s.sessionId)?'Identity matches saved work':'New identity'}</p></div>`).join('')}<p>Current answers are rechecked. Reported history is labeled imported and does not certify independent work.</p><div class="actions">${btn('Cancel','sessions')}${btn('Import as new copies','importCopies','','primary')}${btn('Replace matching sessions…','confirmReplace')}</div>`);}catch(err){dialog('Import not applied',`<p class="bad">${esc(err.message)}</p><p>Existing work has not changed.</p>`);}finally{e.target.value=''}});
document.addEventListener('keydown',e=>{if(!$('.dialog'))return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const els=[...$('.dialog').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);if(!els.length)return;if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}});
$('#modal-host').addEventListener('click',e=>{if(e.target.classList.contains('overlay'))close()});
window.addEventListener('storage',e=>{if(session&&e.key===C.PREFIX+'session:'+session.sessionId){try{const newer=store.read(session.sessionId);if(newer&&newer.localRevision>session.localRevision){clearTimeout(saveTimer);saveStatus='Newer saved work exists in another tab';conflict();}}catch{}}});
window.addEventListener('pagehide',()=>{if(session&&saveTimer)save()});render();
})();
